create schema pos;
create table pos.sync_conflicts(entity text,entity_id text,operation text,expected_version bigint,actual_version bigint,attempted jsonb,current_row jsonb,device_id text);
create or replace function pos.h133_internal_enabled()
returns boolean language sql stable set search_path=pg_catalog,pg_temp as $$
  select coalesce(current_setting('pos.h133_internal', true),'')='on'
$$;
create or replace function pos.guard_entity_version()
returns trigger language plpgsql security definer set search_path=pos,pg_temp as $$
declare op text;
begin
  if pos.h133_internal_enabled() and tg_table_name='products' then return new; end if;
  if tg_op='INSERT' then
    new.sync_version:=1; new.sync_base_version:=null; new.updated_at:=now(); return new;
  end if;
  op:=case when new.deleted_at is not null and old.deleted_at is null then 'delete' else 'upsert' end;
  if new.sync_base_version is not null and new.sync_base_version<>old.sync_version then
    insert into pos.sync_conflicts(entity,entity_id,operation,expected_version,actual_version,
      attempted,current_row,device_id)
    values(tg_table_name,old.id,op,new.sync_base_version,old.sync_version,
      to_jsonb(new)-'sync_base_version',to_jsonb(old),new.sync_device_id);
    return old;
  end if;
  new.sync_version:=old.sync_version+1; new.sync_base_version:=null; new.updated_at:=now(); return new;
end;
$$;

create table pos.clients(id text primary key,nombre text,sync_version bigint not null default 0,sync_base_version bigint,sync_device_id text,updated_at timestamptz,deleted_at timestamptz);
create trigger clients_guard_entity_version before insert or update on pos.clients for each row execute function pos.guard_entity_version();
insert into pos.clients(id,nombre,sync_base_version) values('fixture','Original name',0);
update pos.clients set nombre='Authoritative newer name',sync_base_version=1 where id='fixture';
select 'clients:before' as stage,nombre,sync_version from pos.clients where id='fixture';
insert into pos.clients(id,nombre,sync_base_version) values('fixture','Stale offline name',1) on conflict(id) do update set nombre=excluded.nombre,sync_base_version=excluded.sync_base_version returning nombre,sync_version,sync_base_version;
select 'clients:conflicts' as stage,count(*) from pos.sync_conflicts where entity='clients';

